{"packet_id":"D070-03","doc_id":"D070","jurisdiction":"Newark, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Newark rent control exemptions for new construction, vacant and substantially rehabilitated dwellings","requirement":"Newly constructed multiple dwellings, dwellings vacant at least 18 months or already vacant on the effective date, and substantially reconstructed or rehabilitated dwellings are exempt from Newark's rent increase limits and may charge unrestricted initial rent, subject to Rent Control Board certification.","key_value":"up to 30 years (new construction); 5 years (vacant properties)","coverage_conditions":"Newly constructed multiple dwellings; dwellings vacant at least 18 months or already vacant on the effective date; substantially reconstructed or rehabilitated dwellings.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":30,"basis":"construction","conditional":true},{"type":"other","text":"dwellings vacant at least 18 months or already vacant on the effective date of the section"},{"type":"other","text":"reconstruction or rehabilitation cost during twelve months exceeds 50% of fair market value"}],"per_tenancy":null,"coverage_quotes":["The provisions of the Rent Control Ordinance, which limit the periodic or regular increases in base rentals of dwelling units shall not apply to newly constructed multiple dwellings for a period of time not to exceed the period of amortization of any initial mortgage loan obtained for the multiple dwelling, or for 30 years following completion of construction, whichever is less.","Dwellings which become vacant and remain vacant for a minimum of 18 months or dwellings which are already vacant on the effective date of this section shall be exempt for a period of five years from any restrictions in the rent that the landlord may charge","Substantially reconstructed or rehabilitated dwellings shall not be restricted in initial rent charged, if the Rent Control Board has made the following determinations:"]},"exemptions":"New construction (up to 30 years or mortgage amortization if less); dwellings vacant 18+ months or vacant on effective date (5 years); substantially rehabilitated dwellings (cost over 50% of fair market value).","penalty":null,"effective_date":null,"valid_through":null,"citation":"Newark Mun. Code § 19:2-18","quoted_span":"The provisions of the Rent Control Ordinance, which limit the periodic or regular increases in base rentals of dwelling units shall not apply to newly constructed multiple dwellings for a period of time not to exceed the period of amortization of any initial mortgage loan obtained for the multiple dwelling, or for 30 years following completion of construction, whichever is less.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D070-03","doc_id":"D070","jurisdiction":"Newark, NJ","category":"just_cause_eviction","lifecycle":"enacted","title":"Newark protected tenancy for senior and disabled tenants in conversion evictions","requirement":"The Office of Rent Control Administrator accepts applications from senior citizen and disabled tenants for protected tenancy status from eviction resulting from condominium or cooperative conversions, applying the standards of the Senior Citizens and Disabled Protected Tenancy Act.","key_value":null,"coverage_conditions":"Senior citizen and disabled tenants facing eviction resulting from condominium or cooperative conversions.","applicability":{"conditions":[],"per_tenancy":"senior citizen or disabled tenants in condominium or cooperative conversions","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Newark Mun. Code § 19:2-11","quoted_span":"The Administrator of the Office of Rent Control shall be empowered to accept applications from senior citizen tenants or disabled tenants for the purpose of determining their eligibility for protected tenancy status from eviction resulting from condominium or cooperative conversions.","interaction":null,"relations":[],"confidence":0.85,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D070-03","doc_id":"D070","jurisdiction":"Newark, NJ","category":"just_cause_eviction","lifecycle":"enacted","title":"Newark retaliatory eviction prohibition","requirement":"A landlord may not bring any action to recover possession of a dwelling unit as a reprisal for the tenant's efforts to secure or enforce any right under the rent control chapter.","key_value":null,"coverage_conditions":"All dwelling units covered by the Newark rent control chapter.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Newark Mun. Code § 19:2-14","quoted_span":"No landlord shall bring any action to recover possession of a dwelling unit as a reprisal for the tenant's efforts to secure or enforce any right under this chapter.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
